#!/usr/bin/env python3
from plugins.common.plugin_entry import nv_enrich_plugin
from plugins.common.plugin_utils import get_numpy_frame
import vlm

DEFAULT_PROMPT = (
    "Describi brevemente la escena de forma factual: personas presentes y su vestimenta/EPP "
    "(casco, chaleco, guantes), vehiculos visibles y acciones en curso. No inventes detalles "
    "que no se vean claramente en la imagen."
)


@nv_enrich_plugin("vlm_scene_description", result_scope="frame")
def process_job(job: dict) -> dict:
    frame = job.get("frame")
    if not frame:
        return {}

    image = get_numpy_frame(frame)
    if image is None:
        return {"descriptors": {}}

    params = job.get("params") or {}
    prompt = params.get("prompt") or DEFAULT_PROMPT
    languages = params.get("languages") or ["es"]

    frame_ts = frame.get("ts")
    frame_ts_iso = frame_ts.isoformat() if hasattr(frame_ts, "isoformat") else frame_ts

    result = vlm.describe(
        prompt,
        image,
        frame_id=frame.get("id"),
        frame_ts=frame_ts_iso,
        languages=languages,
        max_image_side=960,
    )

    descriptions = result.get("descriptions", {}) if isinstance(result, dict) else {}
    return {
        "descriptors": {
            "vlm_description": descriptions.get(languages[0], "") if descriptions else "",
        }
    }
